"""Small public models used by the baseline notebook."""

from __future__ import annotations

from typing import Callable, List

import torch
import torch.nn as nn

from metrics.field_score import count_params


class Sine(nn.Module):
    def forward(self, x):
        return torch.sin(x)


def _get_activation(act) -> Callable[[], nn.Module]:
    if isinstance(act, nn.Module):
        return act.__class__
    if callable(act) and act not in {str}:
        return act
    name = str(act).lower()
    if name in {"tanh", "t"}:
        return nn.Tanh
    if name in {"relu", "r"}:
        return nn.ReLU
    if name in {"sine", "sin"}:
        return Sine
    if name == "gelu":
        return nn.GELU
    raise ValueError(f"Unknown activation: {act}")


class TinyMLP(nn.Module):
    def __init__(self, hidden: List[int], activation="tanh", dropout: float = 0.0):
        super().__init__()
        layers = []
        in_dim = 2
        act = _get_activation(activation)
        for h in hidden:
            layers.append(nn.Linear(in_dim, h))
            layers.append(act())
            if dropout > 0.0:
                layers.append(nn.Dropout(dropout))
            in_dim = h
        layers.append(nn.Linear(in_dim, 1))
        self.net = nn.Sequential(*layers)

    def forward(self, x):
        return self.net(x)


__all__ = ["Sine", "TinyMLP", "count_params"]
"""Small training helpers for notebook experiments."""

from __future__ import annotations

from typing import Dict

import torch


def mse_loss(pred, target):
    return ((pred - target) ** 2).mean()


def train_one_epoch(model, optimizer, xy, y, device="cpu") -> Dict[str, float]:
    model.train()
    xy_t = torch.tensor(xy, dtype=torch.float32, device=device)
    y_t = torch.tensor(y, dtype=torch.float32, device=device).unsqueeze(-1)
    optimizer.zero_grad()
    pred = model(xy_t)
    loss = mse_loss(pred, y_t)
    loss.backward()
    optimizer.step()
    return {"loss": float(loss.detach().cpu().item())}


def eval_loss(model, xy, y, device="cpu") -> float:
    model.eval()
    with torch.no_grad():
        xy_t = torch.tensor(xy, dtype=torch.float32, device=device)
        y_t = torch.tensor(y, dtype=torch.float32, device=device).unsqueeze(-1)
        loss = mse_loss(model(xy_t), y_t)
    return float(loss.detach().cpu().item())


__all__ = ["eval_loss", "mse_loss", "train_one_epoch"]
"""Simple models used to explain the scoring behavior."""

from __future__ import annotations

import numpy as np
import torch
import torch.nn as nn


class ConstModel:
    def __init__(self, value: float = 0.0):
        self.value = float(value)

    def __call__(self, xy):
        return np.full((xy.shape[0],), self.value, dtype=np.float32)


class RandomMaskModel:
    def __init__(self, seed: int = 0):
        self.rng = np.random.default_rng(seed)

    def __call__(self, xy):
        return self.rng.random(xy.shape[0]).astype(np.float32)


class TinyDropoutMLP(nn.Module):
    def __init__(self, hidden=(16, 16), p=0.2):
        super().__init__()
        layers = []
        in_dim = 2
        for h in hidden:
            layers.extend((nn.Linear(in_dim, h), nn.Tanh(), nn.Dropout(p)))
            in_dim = h
        layers.append(nn.Linear(in_dim, 1))
        self.net = nn.Sequential(*layers)

    def forward(self, x):
        return self.net(x)


def make_random_tiny_dropout(seed: int = 0, hidden=(16, 16), p=0.2):
    torch.manual_seed(seed)
    return TinyDropoutMLP(hidden=hidden, p=p)


__all__ = [
    "ConstModel",
    "RandomMaskModel",
    "TinyDropoutMLP",
    "make_random_tiny_dropout",
]

